const out = [];
for (const item of $input.all()) {
  const body = item.json.body || item.json || {};
  const hasAudio = !!item.binary?.data;
  out.push({
    json: {
      business_id: body.business_id || 'default',
      owner_phone: String(body.owner_phone || '923000000000').replace(/\D/g, ''),
      customer_name: body.customer_name || body.name || '',
      customer_phone: String(body.customer_phone || body.phone || '').replace(/\D/g, ''),
      phone_number_id: body.phone_number_id || 'YOUR_PHONE_NUMBER_ID',
      transcript: body.transcript || body.text || body.message || '',
      has_audio: hasAudio ? 'yes' : 'no',
      idempotency_key: body.idempotency_key || ('invoice-' + Date.now()),
      received_at: new Date().toISOString()
    },
    binary: item.binary
  });
}
return out;

const base = $('Normalize Invoice Input').item.json;
const text = $input.first().json.text || $input.first().json.transcription || '';
return [{ json: { ...base, transcript: text, source_type: 'audio' } }];

const base = $input.first().json;
let ai = {};
try { ai = JSON.parse(base.choices?.[0]?.message?.content || '{}'); } catch (e) { ai = {}; }
const source = $('Prepare Text Transcript').isExecuted ? $('Prepare Text Transcript').item.json : $('Prepare Voice Transcript').item.json;
const items = Array.isArray(ai.items) ? ai.items : [];
let subtotal = 0;
const cleanItems = items.map((x, i) => {
  const qty = Number(x.quantity);
  const price = Number(x.unit_price);
  const line = Number.isFinite(qty) && Number.isFinite(price) ? qty * price : 0;
  subtotal += line;
  return { name: x.name || ('Item ' + (i + 1)), quantity: qty || 0, unit: x.unit || '', unit_price: price || 0, line_total: line, confidence: Number(x.confidence || 0) };
});
const discount = Number(ai.discount || 0);
const tax = Number(ai.tax || 0);
const total = Math.max(0, subtotal - discount + tax);
const lowConfidence = cleanItems.some(x => x.confidence < 0.75 || !x.name || !x.quantity || !x.unit_price);
const needsReview = ai.needs_review === true || lowConfidence || cleanItems.length === 0;
const invoiceNo = 'INV-' + new Date().toISOString().slice(0,10).replace(/-/g,'') + '-' + Math.floor(1000 + Math.random()*9000);
const receipt = `Invoice ${invoiceNo}\nCustomer: ${ai.customer_name || source.customer_name || 'Walk-in'}\nItems:\n${cleanItems.map((x, idx) => `${idx+1}. ${x.name} ${x.quantity} ${x.unit} x Rs ${x.unit_price} = Rs ${x.line_total}`).join('\n')}\nSubtotal: Rs ${subtotal}\nDiscount: Rs ${discount}\nTax: Rs ${tax}\nTotal: Rs ${total}\nPayment: ${ai.payment_method || 'unknown'}`;
return [{ json: {
  business_id: source.business_id,
  idempotency_key: source.idempotency_key,
  invoice_no: invoiceNo,
  customer_name: ai.customer_name || source.customer_name || '',
  customer_phone: ai.customer_phone || source.customer_phone || '',
  phone_number_id: source.phone_number_id,
  owner_phone: source.owner_phone,
  items: cleanItems,
  items_json: JSON.stringify(cleanItems),
  subtotal, discount, tax, total,
  payment_method: ai.payment_method || 'unknown',
  needs_review: needsReview ? 'yes' : 'no',
  review_reasons: JSON.stringify([...(ai.review_reasons || []), ...(lowConfidence ? ['Low confidence or missing item field'] : [])]),
  receipt_text: receipt,
  status: needsReview ? 'draft_review_required' : 'final_ready',
  created_at: new Date().toISOString()
}}];
